#import "ABMCShortcutListController.h"
#import "ABMCUIHelpers.h"
#import <sqlite3.h>
#define Domain CFSTR("com.huynguyen.actionbuttonmulticlick")
#define Changed CFSTR("com.huynguyen.actionbuttonmulticlick/prefsChanged")
static BOOL ValidID(NSString*v){return[v isKindOfClass:NSString.class]&&[[NSUUID alloc]initWithUUIDString:v]!=nil;}

@interface ABMCShortcutListController () <UISearchBarDelegate>
@end
@implementation ABMCShortcutListController { NSString *_key,*_query;NSArray *_shortcuts;NSMutableOrderedSet *_chosen;BOOL _choosing; }
- (instancetype)initWithPreferenceKey:(NSString*)key{if((self=[super initWithStyle:UITableViewStyleInsetGrouped])){_key=[key copy];self.title=@"指令列表";_chosen=[NSMutableOrderedSet orderedSet];}return self;}
- (void)viewDidLoad{[super viewDidLoad];_query=@"";self.tableView.rowHeight=64;UIView*h=[[UIView alloc]initWithFrame:CGRectMake(0,0,UIScreen.mainScreen.bounds.size.width,72)];UISearchBar*s=[[UISearchBar alloc]initWithFrame:CGRectInset(h.bounds,10,8)];s.placeholder=@"搜索全部快捷指令";s.delegate=self;[h addSubview:s];self.tableView.tableHeaderView=h;self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"选择" style:UIBarButtonItemStylePlain target:self action:@selector(toggleChoosing)];[self reloadShortcuts];}
- (NSArray*)paths{return @[@"/private/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/private/var/mobile/Library/Shortcuts/Shortcuts.db",@"/var/mobile/Library/Shortcuts/Shortcuts.db"];}
- (void)read:(NSString*)path into:(NSMutableDictionary*)results{sqlite3*db=NULL;if(sqlite3_open_v2(path.fileSystemRepresentation,&db,SQLITE_OPEN_READONLY|SQLITE_OPEN_NOMUTEX,NULL)!=SQLITE_OK){if(db)sqlite3_close(db);return;}sqlite3_stmt*s=NULL;const char*q="SELECT x.ZNAME,x.ZWORKFLOWID,COALESCE(i.ZGLYPHNUMBER,0),COALESCE(i.ZBACKGROUNDCOLORVALUE,0) FROM ZSHORTCUT x LEFT JOIN ZSHORTCUTICON i ON i.Z_PK=x.ZICON WHERE x.ZNAME IS NOT NULL AND x.ZWORKFLOWID IS NOT NULL AND COALESCE(x.ZTOMBSTONED,0)=0";if(sqlite3_prepare_v2(db,q,-1,&s,NULL)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW){const char*n=(const char*)sqlite3_column_text(s,0),*i=(const char*)sqlite3_column_text(s,1);if(!n||!i)continue;NSString*name=[[NSString stringWithUTF8String:n]stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet],*identifier=[[NSString stringWithUTF8String:i]uppercaseString];if(name.length&&ValidID(identifier))results[identifier]=@{ @"name":name,@"identifier":identifier,@"glyph":@(sqlite3_column_int64(s,2)),@"color":@(sqlite3_column_int64(s,3)) };}if(s)sqlite3_finalize(s);sqlite3_close(db);}
- (void)reloadShortcuts{NSMutableDictionary*r=[NSMutableDictionary dictionary];for(NSString*p in self.paths)[self read:p into:r];_shortcuts=[[r allValues]sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];[self.tableView reloadData];}
- (NSArray*)visible{return!_query.length?(_shortcuts?:@[]):[_shortcuts filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary*i,NSDictionary*b){return[i[@"name"] localizedCaseInsensitiveContainsString:self->_query];}]];}
- (void)toggleChoosing{if(!_choosing){_choosing=YES;self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"完成" style:UIBarButtonItemStyleDone target:self action:@selector(finishChoosing)];[self.tableView reloadData];return;}[self finishChoosing];}
- (void)finishChoosing{if(_chosen.count<2){UIAlertController*a=[UIAlertController alertControllerWithTitle:@"至少选择两项" message:@"面板需勾选 2–8 个快捷指令。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];return;}NSMutableArray*saved=[NSMutableArray array];for(NSDictionary*i in _chosen.array){NSMutableDictionary*x=[i mutableCopy];UIImage*icon=ABMCWorkflowIconImage([i[@"glyph"]integerValue],[i[@"color"]longLongValue]);NSData*data=icon?UIImagePNGRepresentation(icon):nil;if(data)x[@"iconData"]=data;[saved addObject:x];}NSString*panelID=NSUUID.UUID.UUIDString;CFPropertyListRef v=CFPreferencesCopyAppValue(CFSTR("shortcutPanels"),Domain);NSMutableDictionary*panels=v&&CFGetTypeID(v)==CFDictionaryGetTypeID()?[(__bridge NSDictionary*)v mutableCopy]:[NSMutableDictionary dictionary];if(v)CFRelease(v);panels[panelID]=saved;CFPreferencesSetAppValue(CFSTR("shortcutPanels"),(__bridge CFPropertyListRef)panels,Domain);NSString*action=[@"shortcutpanel:" stringByAppendingString:panelID];CFPreferencesSetAppValue((__bridge CFStringRef)_key,(__bridge CFPropertyListRef)action,Domain);CFPreferencesAppSynchronize(Domain);CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(),Changed,NULL,NULL,YES);[self.navigationController popViewControllerAnimated:YES];}
- (NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return self.visible.count?:1;}
- (UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)p{UITableViewCell*c=[t dequeueReusableCellWithIdentifier:@"ShortcutCell"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"ShortcutCell"];NSArray*items=self.visible;if(!items.count){ABMCApplyLargeIcon(c,ABMCTintedIcon(@"exclamationmark.circle",UIColor.secondaryLabelColor));c.textLabel.text=@"未读取到快捷指令";c.detailTextLabel.text=@"请打开一次快捷指令 App 后刷新";c.selectionStyle=UITableViewCellSelectionStyleNone;c.accessoryType=UITableViewCellAccessoryNone;return c;}NSDictionary*i=items[p.row];NSString*showKey=[@"shortcut." stringByAppendingString:i[@"identifier"]];NSString*showIcon=ABMCDisplayIconToken(showKey,@"");ABMCApplyLargeIcon(c,ABMCTintedIcon(showIcon,nil)?:ABMCIconImageForBundleID(showIcon)?:ABMCWorkflowIconImage([i[@"glyph"]integerValue],[i[@"color"]longLongValue])?:ABMCTintedIcon(@"square.stack.3d.up.fill",nil));c.textLabel.font=[UIFont systemFontOfSize:18];c.textLabel.text=ABMCDisplayTitle(showKey,i[@"name"]);c.detailTextLabel.text=nil;c.selectionStyle=UITableViewCellSelectionStyleDefault;if(_choosing)c.accessoryType=[_chosen containsObject:i]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;else{NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",i[@"identifier"],i[@"name"],i[@"glyph"],i[@"color"]];CFStringRef v=(CFStringRef)CFPreferencesCopyAppValue((__bridge CFStringRef)_key,Domain);c.accessoryType=v&&[(__bridge NSString*)v isEqual:a]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;if(v)CFRelease(v);}return c;}
- (UISwipeActionsConfiguration *)tableView:(UITableView*)t trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath*)p{if(_choosing||!self.visible.count)return nil;NSDictionary*i=self.visible[p.row];NSString*key=[@"shortcut." stringByAppendingString:i[@"identifier"]];UIContextualAction*edit=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:@"修改" handler:^(__unused UIContextualAction*a,__unused UIView*v,void(^done)(BOOL)){ABMCShowPresentationEditor(self,key,i[@"name"],@"square.stack.3d.up.fill",^{[self.tableView reloadData];done(YES);});}];edit.backgroundColor=UIColor.systemBlueColor;UIContextualAction*clear=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:@"清空" handler:^(__unused UIContextualAction*a,__unused UIView*v,void(^done)(BOOL)){ABMCClearPresentationOverride(key);[self.tableView reloadData];done(YES);}];clear.backgroundColor=UIColor.systemGrayColor;return[UISwipeActionsConfiguration configurationWithActions:@[clear,edit]];}
- (void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)p{NSDictionary*i=self.visible[p.row];if(_choosing){if([_chosen containsObject:i])[_chosen removeObject:i];else if(_chosen.count<8)[_chosen addObject:i];else{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"最多 8 项" message:@"快捷指令面板最多展示 8 项。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];}[t reloadRowsAtIndexPaths:@[p] withRowAnimation:UITableViewRowAnimationNone];return;}NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",i[@"identifier"],i[@"name"],i[@"glyph"],i[@"color"]];CFPreferencesSetAppValue((__bridge CFStringRef)_key,(__bridge CFPropertyListRef)a,Domain);CFPreferencesAppSynchronize(Domain);CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(),Changed,NULL,NULL,YES);[self.navigationController popViewControllerAnimated:YES];}
- (void)searchBar:(UISearchBar*)s textDidChange:(NSString*)text{_query=[text copy]?:@"";[UIView performWithoutAnimation:^{[self.tableView reloadData];}];}
@end
